#ifndef BSP_SAI_H
#define BSP_SAI_H

#include <stddef.h>
#include "stm32f7xx_hal.h"

/* After hardware_init(), configure SAI1 A (master TX) and B (synchronous RX).
 * RX uses the clocks generated by block A once a transfer is active. */
HAL_StatusTypeDef bsp_sai_init(SAI_HandleTypeDef *tx, SAI_HandleTypeDef *rx);

/* Blocking transfers, serialized by the caller. One frame contains two 16-bit samples. */
HAL_StatusTypeDef bsp_sai_record(SAI_HandleTypeDef *tx, SAI_HandleTypeDef *rx, int16_t *pcm,
                                 size_t frames);
HAL_StatusTypeDef bsp_sai_play(SAI_HandleTypeDef *tx, const int16_t *pcm, size_t frames);

#endif
